//! Cargo-driven `libpng.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x732b0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fefd000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fefd000000u64)),
        o => panic!("libpng-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:zlib", "engine:pseh", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames", "body"],
        "x86_64" => &["engine:c:zlib", "engine:pseh", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "body"],
        "aarch64" => &["engine:c:zlib", "engine:pseh", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("libpng_shims", &["vendor/libpng/png.c", "vendor/libpng/pngerror.c", "vendor/libpng/pngget.c", "vendor/libpng/pngmem.c", "vendor/libpng/pngpread.c", "vendor/libpng/pngread.c", "vendor/libpng/pngrio.c", "vendor/libpng/pngrtran.c", "vendor/libpng/pngrutil.c", "vendor/libpng/pngset.c", "vendor/libpng/pngtrans.c", "vendor/libpng/pngwio.c", "vendor/libpng/pngwrite.c", "vendor/libpng/pngwtran.c", "vendor/libpng/pngwutil.c"])
        .whole_c_objects("libpng_shims")
        .spec2def("vendor/libpng/libpng.spec", "libpng.dll")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
